-- ════════════════════════════════════════════════════════════════════════
-- MIGRACIÓN 031 — 6 cursos nuevos: Prompt Engineering Práctico, Introducción
-- a Bases de Datos, Programación Orientada a Objetos, Paradigmas de la
-- Programación, React y Vue.js — insertados directamente en public.courses
-- (Fase 1: Migración de Contenido), sin tocar código de la app.
-- ════════════════════════════════════════════════════════════════════════

insert into public.courses
  (id, title, description, ai_instructions, icon, color, category, subcategory, difficulty, locked, modules)
values
  ('course-prompt-practico', 'Prompt Engineering Práctico: De la Teoría a Proyectos Reales', 'El complemento práctico de "Prompt Engineering desde cero": menos teoría, más ejercicios reales — depurar prompts que fallan, extraer datos, trabajar con código y encadenar tareas.', 'Eres el Mago, tutor de Prompt Engineering Práctico en Oliver Academy. Este curso es el complemento hands-on de "Prompt Engineering desde cero" — asume que el estudiante ya conoce los conceptos teóricos (zero-shot, few-shot, CoT) y enfócate en ejercicios reales: qué hacer cuando un prompt no funciona, cómo iterar, cómo pedir código. Sé práctico y directo.', '🛠️', '#c084fc', 'Inteligencia Artificial', 'Prompt Engineering', null, false, '[{"id":"pp-01","order":1,"type":"text","title":"De la teoría a la práctica","description":"Por qué conocer las técnicas no es lo mismo que escribir buenos prompts bajo presión real.","content":"<h2>El salto que nadie te avisa</h2><p>Conocer zero-shot, few-shot y chain-of-thought es el vocabulario. Escribir un prompt que funcione a la primera vez, para una tarea real y ambigua, es la habilidad — y esa habilidad se construye con práctica, no con memorizar definiciones.</p><h2>El ciclo real de trabajo con IA</h2><p>En la práctica, casi nadie escribe el prompt perfecto al primer intento. El flujo real es: escribir → probar → ver qué falló → ajustar → repetir. Este curso está construido alrededor de ESE ciclo, no de teoría adicional.</p><div class=\"tip\">💡 Si \"Prompt Engineering desde cero\" te dio el mapa, este curso es manejar el coche — vas a fallar prompts a propósito en los ejercicios, para aprender a reconocer POR QUÉ fallan.</div>","exercises":[{"id":"pp-01-1","type":"challenge","prompt":"Escribe un prompt para pedirle a una IA que te resuma un artículo, sin pensarlo demasiado. Guárdalo — lo vas a comparar con una versión mejorada más adelante en el curso. Compártelo con tu mascota.","solution":""}],"resources":[],"quiz":{"question":"¿Cuál es el enfoque central de este curso, a diferencia de \"Prompt Engineering desde cero\"?","options":["Repetir la misma teoría con otras palabras","Práctica real: iterar, depurar y ajustar prompts que no funcionan a la primera","Aprender a programar en Python","Memorizar más técnicas nuevas sin practicarlas"],"correctIndex":1},"comments":[]},{"id":"pp-02","order":2,"type":"text","title":"Anatomía de un prompt real","description":"Los cuatro ingredientes que distinguen un prompt vago de uno que funciona.","content":"<h2>Los cuatro ingredientes</h2><ul><li><strong>Contexto:</strong> quién eres, para quién es esto, qué información de fondo necesita el modelo.</li><li><strong>Tarea:</strong> qué quieres exactamente que haga, sin ambigüedad.</li><li><strong>Formato:</strong> cómo quieres la respuesta (lista, tabla, JSON, cierto número de palabras).</li><li><strong>Restricciones:</strong> qué evitar, qué tono usar, qué límites respetar.</li></ul><div class=\"bad\">❌ <strong>Prompt vago:</strong> \"Resúmeme esto.\"</div><div class=\"example\">✅ <strong>Prompt completo:</strong> \"Eres un editor de noticias. Resume el siguiente artículo en 3 viñetas, cada una de máximo 20 palabras, sin usar tecnicismos. [artículo]\"</div><div class=\"tip\">💡 No todos los prompts necesitan los cuatro ingredientes al máximo detalle — pero cuando un prompt \"no funciona\", casi siempre falta uno de estos cuatro, no magia adicional.</div>","exercises":[{"id":"pp-02-1","type":"challenge","prompt":"Toma el prompt vago que escribiste en el módulo anterior y reescríbelo agregando los 4 ingredientes: contexto, tarea, formato, restricciones. Compara ambas versiones y comparte con tu mascota.","solution":""}],"resources":[],"quiz":{"question":"¿Cuáles son los 4 ingredientes de un prompt completo según este módulo?","options":["Longitud, idioma, emojis y mayúsculas","Contexto, tarea, formato y restricciones","Nombre del modelo, fecha, hora y firma","Solo la tarea es necesaria"],"correctIndex":1},"comments":[]},{"id":"pp-03","order":3,"type":"text","title":"Iterar como un profesional: depurar un prompt que falla","description":"Un prompt malo casi nunca se \"arregla\" reescribiéndolo entero — se diagnostica primero.","content":"<h2>El error común: reescribir todo desde cero</h2><p>Cuando un prompt no da el resultado esperado, la reacción instintiva es borrar todo y empezar de nuevo. Un enfoque más eficiente es diagnosticar QUÉ parte falló antes de tocar el resto.</p><h2>Preguntas de diagnóstico</h2><ul><li>¿El modelo entendió mal la tarea, o la entendió bien pero el formato de salida no sirve?</li><li>¿Falta contexto que el modelo no podía adivinar?</li><li>¿La respuesta es genérica porque el prompt era genérico?</li><li>¿Un ejemplo (few-shot) resolvería la ambigüedad más rápido que más instrucciones de texto?</li></ul><div class=\"warn\">⚠️ Un síntoma clásico: si el modelo \"alucina\" datos que no le diste, casi siempre significa que le pediste algo que no puede saber con certeza — la solución no es \"pedirle que no invente\", es darle la información real o pedirle que declare cuando no sabe algo.</div><div class=\"tip\">💡 Cambiar UNA cosa a la vez entre intentos (agregar un ejemplo, ajustar el formato) te deja saber qué cambio realmente ayudó — cambiar todo de golpe te deja sin esa información.</div>","exercises":[{"id":"pp-03-1","type":"challenge","prompt":"Piensa en un prompt que hayas escrito que no dio el resultado esperado (o inventa uno). Diagnostica cuál de las 4 preguntas del módulo explica mejor por qué falló. Compártelo con tu mascota.","solution":""}],"resources":[],"quiz":{"question":"Según el módulo, ¿cuál es el problema de reescribir todo el prompt desde cero cuando falla?","options":["Nunca hay que reescribir nada","Pierdes la información de qué parte específica causó el problema","Es ilegal hacerlo","Siempre funciona mejor que diagnosticar"],"correctIndex":1},"comments":[]},{"id":"pp-04","order":4,"type":"text","title":"Prompts para tareas reales: resumir, extraer y clasificar","description":"Tres tareas que cubren la mayoría del trabajo cotidiano con IA.","content":"<h2>Resumir: la longitud y el formato importan más que \"hazlo corto\"</h2><div class=\"example\">🧪 \"Resume este texto en un párrafo de máximo 80 palabras, para alguien que no leyó el original, priorizando conclusiones sobre detalles.\" — mucho más útil que \"resume esto\".</div><h2>Extraer datos: pide un formato estructurado</h2><p>Cuando necesitas datos específicos de un texto (nombres, fechas, cifras), pedir el resultado en formato <strong>JSON o tabla</strong> con campos exactos hace que el resultado sea directamente usable, no solo legible.</p><div class=\"example\">🧪 \"Extrae de este correo: nombre del remitente, fecha mencionada, y monto solicitado. Devuélvelo como JSON con las claves nombre, fecha, monto.\"</div><h2>Clasificar: define las categorías explícitamente</h2><p>Pedir \"clasifica este texto\" sin dar las categorías posibles deja que el modelo invente su propio sistema, que puede no coincidir con lo que necesitas. Siempre lista las categorías válidas.</p><div class=\"tip\">💡 Estas tres tareas (resumir, extraer, clasificar) son la base de automatizaciones reales — desde ordenar correos hasta procesar formularios — y todas mejoran con el mismo principio: sé específico sobre el formato de salida.</div>","exercises":[{"id":"pp-04-1","type":"challenge","prompt":"Elige un texto largo que tengas a mano (un correo, un artículo) y practica las 3 tareas: pide un resumen con restricciones específicas, extrae 2-3 datos en formato JSON, y clasifícalo en categorías que tú definas. Comparte los resultados con tu mascota.","solution":""}],"resources":[],"quiz":{"question":"¿Por qué es mejor pedir datos extraídos en formato JSON o tabla, en vez de texto libre?","options":["Es más elegante visualmente","El resultado queda directamente usable/estructurado, no solo legible","JSON es el único formato que entiende una IA","No hay ninguna ventaja real"],"correctIndex":1},"comments":[]},{"id":"pp-05","order":5,"type":"text","title":"Prompts para código: pedir, revisar y depurar con IA","description":"Cómo usar un asistente de IA como par de programación, no como oráculo infalible.","content":"<h2>Pedir código: contexto técnico específico</h2><p>Un buen prompt para código incluye el lenguaje, la versión/framework si aplica, y las restricciones técnicas reales (rendimiento, estilo del proyecto, librerías ya en uso) — igual que le darías contexto a un compañero nuevo en el equipo.</p><h2>Revisar código: pide una revisión estructurada</h2><div class=\"example\">🧪 \"Revisa esta función buscando: bugs, casos límite no manejados, y oportunidades de simplificación. Para cada hallazgo, indica la línea y por qué es un problema.\" — mucho más útil que \"¿está bien este código?\".</div><h2>Depurar: dale el error completo, no un resumen</h2><p>Al pedir ayuda para depurar, pega el mensaje de error COMPLETO (no \"me da un error\"), el código relevante, y qué esperabas que pasara — entre más contexto exacto, menos vueltas necesita el modelo para ayudarte.</p><div class=\"warn\">⚠️ Un asistente de IA puede generar código que se ve correcto pero tiene errores sutiles — SIEMPRE prueba el código generado, no lo copies y pegues a producción sin revisarlo. Es un asistente, no un reemplazo del criterio técnico.</div>","exercises":[{"id":"pp-05-1","type":"challenge","prompt":"Pídele a una IA que revise una función corta que hayas escrito (o una del curso de Fundamentos de Programación), usando el prompt estructurado de \"revisar código\" del módulo. Comparte qué encontró con tu mascota.","solution":""}],"resources":[],"quiz":{"question":"¿Qué se recomienda SIEMPRE hacer con código generado por IA antes de usarlo?","options":["Copiarlo directo a producción sin revisar","Probarlo y revisarlo, porque puede tener errores sutiles aunque se vea correcto","Confiar ciegamente si el modelo dice que está bien","Nunca usar código generado por IA"],"correctIndex":1},"comments":[]},{"id":"pp-06","order":6,"type":"text","title":"Encadenar prompts: un mini-proyecto de flujo completo","description":"Cierre del curso: cómo dividir una tarea grande en varios prompts conectados.","content":"<h2>El problema de un solo prompt gigante</h2><p>Para tareas complejas (investigar un tema, escribir un informe con varias secciones), un solo prompt gigante suele dar resultados mediocres — el modelo intenta hacer demasiado a la vez. <strong>Encadenar prompts</strong> — donde la salida de uno alimenta al siguiente — casi siempre da mejores resultados.</p><h2>Ejemplo de un flujo encadenado</h2><ol><li>Prompt 1: \"Genera 5 preguntas clave para investigar [tema].\"</li><li>Prompt 2 (usando la salida del 1): \"Responde esta pregunta con evidencia: [pregunta 1 de la lista].\"</li><li>Prompt 3 (usando las respuestas anteriores): \"Combina estas respuestas en un informe de 300 palabras con introducción y conclusión.\"</li></ol><div class=\"tip\">💡 Este patrón — dividir, resolver cada parte, combinar — es el mismo principio de \"dividir problemas en partes\" que viste en Fundamentos de Programación, aplicado a prompts en vez de código.</div><h2>Cierre del curso</h2><div class=\"tip\">💡 Con esto completas el complemento práctico de Prompt Engineering: anatomía de un prompt real, cómo diagnosticar y depurar cuando algo falla, tareas concretas (resumir/extraer/clasificar), trabajo con código, y finalmente encadenar prompts para tareas complejas. La teoría te dio el vocabulario — esta práctica te da el reflejo de iterar rápido cuando algo no sale bien a la primera, que es lo que realmente se usa día a día.</div>","exercises":[{"id":"pp-06-1","type":"challenge","prompt":"Diseña (por escrito, sin necesidad de ejecutarlo) un flujo de 3 prompts encadenados para una tarea que te interese (planear un viaje, estudiar para un examen, organizar un proyecto). Comparte tu flujo con tu mascota.","solution":""}],"resources":[],"quiz":{"question":"¿Por qué encadenar varios prompts suele funcionar mejor que un solo prompt gigante para tareas complejas?","options":["Porque siempre es más rápido","Porque el modelo puede enfocarse en una parte a la vez, en vez de hacer demasiado de golpe","Porque usa menos texto en total","No hay ninguna ventaja real"],"correctIndex":1},"comments":[]}]'::jsonb),
  ('course-bases-datos', 'Introducción a Bases de Datos', 'Qué es una base de datos, cómo se organizan en tablas, SQL básico, relaciones entre tablas y cuándo elegir SQL vs. NoSQL.', 'Eres el Mago, tutor de Introducción a Bases de Datos en Oliver Academy. Explica cada concepto con ejemplos concretos (una lista de estudiantes, un catálogo de productos) antes de la sintaxis SQL. Anima al estudiante a pensar en tablas como hojas de cálculo relacionadas entre sí.', '🗄️', '#0ea5e9', 'Programación', 'Bases de Datos', null, false, '[{"id":"bd-01","order":1,"type":"text","title":"¿Qué es una base de datos y por qué no usamos solo archivos?","description":"El problema que resuelven las bases de datos, más allá de \"guardar información\".","content":"<h2>El problema de los archivos sueltos</h2><p>Podrías guardar información en archivos de texto o Excel — pero eso se vuelve inmanejable rápido: ¿cómo buscas algo específico entre miles de registros? ¿Qué pasa si dos personas editan el mismo archivo a la vez? ¿Cómo evitas que el mismo dato se escriba distinto en dos lugares?</p><h2>Lo que resuelve una base de datos</h2><ul><li><strong>Búsqueda rápida</strong> incluso con millones de registros.</li><li><strong>Acceso simultáneo</strong> de muchos usuarios/programas sin corromper los datos.</li><li><strong>Consistencia</strong> — reglas que evitan datos contradictorios o inválidos.</li><li><strong>Estructura</strong> que permite consultar la información de formas que ni siquiera anticipaste al guardarla.</li></ul><div class=\"tip\">💡 Toda esta plataforma (Oliver Academy) guarda perfiles, cursos, tareas y progreso en una base de datos real (Supabase/PostgreSQL) — sin eso, cada acción tuya se perdería o chocaría con la de otro estudiante usando la app al mismo tiempo.</div>","exercises":[{"id":"bd-01-1","type":"challenge","prompt":"Piensa en una app que uses (redes sociales, banco, tienda en línea) y describe qué información crees que guarda en una base de datos, y por qué un simple archivo de texto no funcionaría para eso. Compártelo con tu mascota.","solution":""}],"resources":[],"quiz":{"question":"¿Cuál NO es un problema típico de usar solo archivos sueltos para guardar datos?","options":["Búsqueda lenta con muchos registros","Riesgo de que dos personas editen y corrompan el mismo archivo","Que sean gratis de usar","Inconsistencia entre copias del mismo dato"],"correctIndex":2},"comments":[]},{"id":"bd-02","order":2,"type":"text","title":"Bases de datos relacionales: tablas, filas y columnas","description":"Piensa en una hoja de cálculo — con reglas mucho más estrictas.","content":"<h2>La analogía de la hoja de cálculo</h2><p>Una <strong>tabla</strong> se parece a una hoja de cálculo: cada <strong>columna</strong> es un tipo de dato (nombre, edad, email), y cada <strong>fila</strong> es un registro individual (una persona, un producto).</p><div class=\"example\">🧪 <strong>Tabla \"estudiantes\":</strong><br>id | nombre | edad | curso<br>1 | Ana | 16 | Matemáticas<br>2 | Luis | 17 | Programación</div><h2>Tipos de datos por columna</h2><p>A diferencia de una hoja de cálculo libre, cada columna en una base de datos relacional tiene un <strong>tipo definido</strong> (número entero, texto, fecha, booleano) — la base de datos RECHAZA intentar meter texto en una columna numérica, evitando errores silenciosos.</p><h2>La clave primaria: el identificador único</h2><p>Cada tabla tiene típicamente una <strong>clave primaria</strong> (como \"id\") — un valor único que identifica sin ambigüedad cada fila, incluso si dos personas tienen exactamente el mismo nombre.</p><div class=\"tip\">💡 Por eso los sistemas usan \"id de usuario\" internamente en vez de solo el nombre — dos \"Juan Pérez\" distintos necesitan poder distinguirse sin error.</div>","exercises":[{"id":"bd-02-1","type":"challenge","prompt":"Diseña en papel (o texto) una tabla simple para un catálogo de libros: define 4 columnas con su tipo de dato, y agrega 3 filas de ejemplo con una clave primaria. Compártelo con tu mascota.","solution":""}],"resources":[],"quiz":{"question":"¿Para qué sirve la clave primaria de una tabla?","options":["Para decorar la tabla","Para identificar sin ambigüedad cada fila, aunque otros datos se repitan","Solo aplica a tablas con nombres","Para borrar filas automáticamente"],"correctIndex":1},"comments":[]},{"id":"bd-03","order":3,"type":"text","title":"SQL básico: SELECT, WHERE, INSERT, UPDATE, DELETE","description":"El lenguaje declarativo con el que le \"preguntas\" a una base de datos.","content":"<h2>SQL: le dices QUÉ quieres, no CÓMO buscarlo</h2><p><strong>SQL</strong> (Structured Query Language) es declarativo — como viste en el curso del Paradigma de React, describes el resultado que quieres, y el motor de base de datos decide cómo obtenerlo eficientemente.</p><h2>Las cuatro operaciones básicas (CRUD)</h2><div class=\"example\">🧪 <strong>Leer (SELECT):</strong><br><code>SELECT nombre, curso FROM estudiantes WHERE edad > 16;</code><br><strong>Crear (INSERT):</strong><br><code>INSERT INTO estudiantes (nombre, edad, curso) VALUES (''Marco'', 15, ''Lógica'');</code><br><strong>Actualizar (UPDATE):</strong><br><code>UPDATE estudiantes SET curso = ''Bases de Datos'' WHERE id = 2;</code><br><strong>Eliminar (DELETE):</strong><br><code>DELETE FROM estudiantes WHERE id = 1;</code></div><h2>WHERE: filtrar qué filas afecta cada operación</h2><p>La cláusula <code>WHERE</code> es crítica — sin ella, un <code>UPDATE</code> o <code>DELETE</code> afecta TODAS las filas de la tabla, no solo la que querías.</p><div class=\"warn\">⚠️ Olvidar el <code>WHERE</code> en un UPDATE o DELETE es uno de los errores más temidos (y comunes) en bases de datos reales — puede borrar o modificar toda una tabla de producción en un segundo. Siempre verifica el WHERE antes de ejecutar.</div>","exercises":[{"id":"bd-03-1","type":"challenge","prompt":"Escribe (en papel, sin ejecutarlo) las 4 operaciones CRUD para la tabla de libros que diseñaste en el módulo anterior: un SELECT con filtro, un INSERT, un UPDATE y un DELETE, cada uno con su WHERE correspondiente. Compártelo con tu mascota.","solution":""}],"resources":[],"quiz":{"question":"¿Qué pasa si ejecutas un UPDATE o DELETE sin cláusula WHERE?","options":["No pasa nada, es más seguro","Afecta a TODAS las filas de la tabla, no solo la que querías","La base de datos lo rechaza automáticamente siempre","Solo afecta la primera fila"],"correctIndex":1},"comments":[]},{"id":"bd-04","order":4,"type":"text","title":"Relaciones entre tablas: claves foráneas y JOINs","description":"Cómo evitar repetir información conectando tablas entre sí.","content":"<h2>El problema de una sola tabla gigante</h2><p>Si guardaras el nombre del curso completo (con descripción, profesor, etc.) repetido en cada fila de estudiante, cualquier cambio al curso requeriría actualizar cientos de filas — y un error de tipeo podría hacer que \"Matemáticas\" y \"matemáticas\" parezcan cursos distintos.</p><h2>La solución: separar en tablas y conectarlas</h2><p>En vez de eso, se crean tablas separadas (<code>estudiantes</code> y <code>cursos</code>), y la tabla de estudiantes solo guarda una <strong>clave foránea</strong> — el id del curso al que pertenece, apuntando a la clave primaria de la tabla <code>cursos</code>.</p><div class=\"example\">🧪 <strong>Tabla cursos:</strong> id=1, nombre=\"Matemáticas\"<br><strong>Tabla estudiantes:</strong> id=1, nombre=\"Ana\", curso_id=1<br>Ana \"apunta\" al curso 1, sin repetir el nombre completo del curso en su propia fila.</div><h2>JOIN: combinar tablas relacionadas en una consulta</h2><div class=\"example\">🧪 <code>SELECT estudiantes.nombre, cursos.nombre<br>FROM estudiantes<br>JOIN cursos ON estudiantes.curso_id = cursos.id;</code><br>Esto combina ambas tablas para mostrar el nombre del estudiante JUNTO con el nombre real de su curso, sin haberlo duplicado en ningún lado.</div><div class=\"tip\">💡 Este mismo patrón (clave foránea + JOIN) es exactamente cómo esta plataforma conecta, por ejemplo, cada tarea con el estudiante que la entregó y el curso al que pertenece, sin repetir esa información en cada fila.</div>","exercises":[{"id":"bd-04-1","type":"challenge","prompt":"Diseña dos tablas relacionadas (por ejemplo: \"pedidos\" y \"productos\") con una clave foránea entre ellas, y escribe el JOIN que las combinaría en una consulta. Compártelo con tu mascota.","solution":""}],"resources":[],"quiz":{"question":"¿Qué es una clave foránea?","options":["Una clave primaria duplicada","Un valor en una tabla que apunta a la clave primaria de otra tabla","Una contraseña de la base de datos","Un tipo de dato especial para texto"],"correctIndex":1},"comments":[]},{"id":"bd-05","order":5,"type":"text","title":"Normalización: por qué no duplicar datos","description":"El principio de diseño que evita inconsistencias silenciosas.","content":"<h2>El problema de la duplicación</h2><p>Si el nombre de un curso está guardado en 50 filas distintas de estudiantes, y necesitas corregir un error de tipeo, tendrías que encontrar y corregir las 50 — y si te saltas una, tu base de datos queda con datos <strong>inconsistentes</strong> silenciosamente (dos versiones distintas de \"la misma\" información).</p><h2>Normalización: cada dato vive en un solo lugar</h2><p>La <strong>normalización</strong> es el proceso de organizar tablas para que cada pieza de información se guarde en un solo lugar, y todo lo demás la referencie mediante claves foráneas — el mismo patrón que viste en el módulo anterior, aplicado como principio general de diseño.</p><div class=\"example\">🧪 En vez de repetir \"Ciudad de México, México\" en cada fila de una tabla de direcciones, se crea una tabla separada de ciudades, y las direcciones solo guardan el id de la ciudad correspondiente.</div><h2>Cuándo \"romper\" la normalización (a propósito)</h2><div class=\"warn\">⚠️ La normalización estricta a veces hace las consultas más lentas (por tener que combinar muchas tablas). En sistemas con necesidades específicas de velocidad, a veces se duplica información deliberadamente (desnormalización) — pero eso es una decisión consciente de rendimiento, no un descuido de diseño.</div><div class=\"tip\">💡 Regla práctica para empezar: si te encuentras copiando y pegando el mismo dato en múltiples filas, probablemente ese dato debería vivir en su propia tabla, referenciada por clave foránea.</div>","exercises":[{"id":"bd-05-1","type":"challenge","prompt":"Revisa la tabla que diseñaste en el módulo 2 (libros). ¿Hay algún dato que se repetiría si tuvieras muchos libros del mismo autor o categoría? Rediséñalo separándolo en una tabla propia. Comparte con tu mascota.","solution":""}],"resources":[],"quiz":{"question":"¿Qué problema evita la normalización?","options":["Que las consultas sean más rápidas siempre","Inconsistencias silenciosas por tener el mismo dato duplicado en múltiples lugares","Que se necesiten claves primarias","Que las tablas tengan columnas"],"correctIndex":1},"comments":[]},{"id":"bd-06","order":6,"type":"text","title":"NoSQL y cuándo NO usar una base de datos relacional","description":"Cierre del curso: las tablas no son la única forma de organizar datos.","content":"<h2>Cuando la estructura rígida de tablas no encaja</h2><p>Las bases de datos relacionales (SQL) son excelentes cuando los datos tienen una estructura clara y consistente. Pero algunos datos son más naturales de guardar como documentos flexibles, listas anidadas, o grafos de relaciones complejas — ahí es donde entran las bases de datos <strong>NoSQL</strong>.</p><h2>Principales tipos de NoSQL</h2><ul><li><strong>Documentales</strong> (como MongoDB): guardan objetos tipo JSON, flexibles, sin un esquema de columnas fijo.</li><li><strong>Clave-valor</strong> (como Redis): extremadamente rápidas para buscar por un identificador único, usadas mucho para caché.</li><li><strong>De grafos</strong> (como Neo4j): optimizadas para relaciones complejas entre entidades (redes sociales, recomendaciones).</li></ul><div class=\"example\">🧪 Guardar el historial de chat de un usuario, donde cada mensaje puede tener una estructura ligeramente distinta (con o sin adjuntos, con o sin respuesta citada), encaja más naturalmente en un documento flexible que en una tabla rígida de columnas fijas.</div><h2>No es \"SQL vs. NoSQL\", es \"la herramienta correcta para el problema\"</h2><div class=\"tip\">💡 Muchos sistemas reales (incluida esta plataforma) usan una base de datos relacional como núcleo, y a veces combinan piezas NoSQL (como caché) donde tiene sentido — la pregunta correcta nunca es \"¿cuál es mejor?\" en abstracto, sino \"¿qué forma tienen realmente mis datos?\".</div><h2>Cierre del curso</h2><div class=\"tip\">💡 Con esto completas un recorrido por bases de datos: qué problema resuelven, cómo se organizan en tablas, SQL básico (CRUD), relaciones entre tablas, normalización, y finalmente cuándo NoSQL encaja mejor que una base relacional. Cada aplicación real que uses a diario — desde esta plataforma hasta cualquier red social — depende de decisiones de este tipo, tomadas por alguien que entendía estos principios.</div>","exercises":[{"id":"bd-06-1","type":"challenge","prompt":"¿Se te ocurre un tipo de dato de tu vida cotidiana que encajaría mejor en un formato flexible tipo documento (NoSQL) que en una tabla rígida? Descríbelo y explica por qué. Compártelo con tu mascota.","solution":""}],"resources":[],"quiz":{"question":"¿Cuándo tiene más sentido usar NoSQL en vez de una base de datos relacional?","options":["Siempre, NoSQL es superior","Cuando los datos son más naturales como documentos flexibles, o requieren velocidad extrema por clave, o relaciones tipo grafo","Nunca, SQL siempre es mejor","Solo para guardar contraseñas"],"correctIndex":1},"comments":[]}]'::jsonb),
  ('course-poo', 'Introducción a la Programación Orientada a Objetos', 'Clases, objetos, encapsulamiento, herencia y polimorfismo — el paradigma que organiza el código como "cosas" con propiedades y comportamiento.', 'Eres el Mago, tutor de Programación Orientada a Objetos en Oliver Academy. Usa analogías del mundo real (vehículos, animales, personajes de videojuego) para cada pilar de POO antes de mostrar código, y sé honesto sobre cuándo POO es la herramienta correcta y cuándo no.', '🧬', '#f472b6', 'Programación', 'Paradigmas', null, false, '[{"id":"poo-01","order":1,"type":"text","title":"¿Qué es la programación orientada a objetos?","description":"Modelar el código como \"cosas\" con datos y comportamiento propio, no como una lista de instrucciones sueltas.","content":"<h2>La idea central</h2><p>La <strong>Programación Orientada a Objetos (POO)</strong> organiza el código alrededor de <strong>objetos</strong> — unidades que combinan datos (propiedades) y comportamiento (métodos) relacionados entre sí, en vez de tener datos y funciones completamente separados.</p><h2>Un cambio de perspectiva, no solo de sintaxis</h2><div class=\"example\">🧪 En vez de tener una variable \"vida_perro\" y una función separada \"hacer_ladrar(nombre_variable)\", POO agrupa esto en un objeto <code>perro</code> que TIENE su propia vida y SABE ladrar por sí mismo — <code>perro.ladrar()</code>.</div><h2>Por qué surgió este paradigma</h2><p>A medida que los programas crecieron en tamaño (los años 60-80 vieron sistemas cada vez más grandes), organizar el código como \"cosas\" con identidad propia resultó más fácil de razonar y mantener que tener cientos de funciones sueltas operando sobre datos genéricos flotantes.</p><div class=\"tip\">💡 Este curso complementa el de Paradigmas de la Programación (donde POO es solo uno de varios estilos vistos brevemente) — aquí profundizamos específicamente en POO con ejemplos completos.</div>","exercises":[{"id":"poo-01-1","type":"challenge","prompt":"Piensa en un objeto de tu vida cotidiana (un coche, una mascota, un celular) y lista 3 propiedades (datos) y 3 comportamientos (acciones) que tendría si fuera un objeto en código. Compártelo con tu mascota.","solution":""}],"resources":[],"quiz":{"question":"¿Qué combina un objeto en programación orientada a objetos?","options":["Solo datos, sin comportamiento","Solo funciones, sin datos","Datos (propiedades) y comportamiento (métodos) relacionados","Nada, es un concepto abstracto sin uso real"],"correctIndex":2},"comments":[]},{"id":"poo-02","order":2,"type":"text","title":"Clases y objetos: el molde y la instancia","description":"La diferencia entre \"el diseño de una cosa\" y \"una cosa real\" de ese diseño.","content":"<h2>La clase: un molde, no una cosa real todavía</h2><p>Una <strong>clase</strong> es la definición/plantilla de qué propiedades y métodos tendrá algo — como el plano de una casa, no la casa en sí.</p><h2>El objeto (instancia): la cosa real, construida a partir del molde</h2><div class=\"example\">🧪 <code>class Perro {<br>&nbsp;&nbsp;constructor(nombre) {<br>&nbsp;&nbsp;&nbsp;&nbsp;this.nombre = nombre<br>&nbsp;&nbsp;&nbsp;&nbsp;this.energia = 100<br>&nbsp;&nbsp;}<br>&nbsp;&nbsp;ladrar() {<br>&nbsp;&nbsp;&nbsp;&nbsp;return this.nombre + \" dice: ¡Guau!\"<br>&nbsp;&nbsp;}<br>}<br><br>const rex = new Perro(\"Rex\")  // rex es un OBJETO, instancia de la clase Perro<br>const luna = new Perro(\"Luna\")  // luna es OTRO objeto, independiente de rex</code></div><p>De una sola clase <code>Perro</code> puedes crear tantos objetos (<strong>instancias</strong>) como necesites, cada uno con sus propios valores de <code>nombre</code> y <code>energia</code>, pero compartiendo la misma estructura y comportamiento definidos por la clase.</p><div class=\"tip\">💡 <code>this</code> dentro de un método siempre se refiere al objeto específico sobre el que se llamó — <code>rex.ladrar()</code> usa el <code>nombre</code> de rex, no el de luna, aunque ambos vengan de la misma clase.</div>","exercises":[{"id":"poo-02-1","type":"challenge","prompt":"Diseña (en pseudocódigo o el lenguaje que prefieras) una clase \"Estudiante\" con al menos 2 propiedades y 1 método, y crea 2 instancias distintas de esa clase con valores diferentes. Comparte tu código con tu mascota.","solution":""}],"resources":[],"quiz":{"question":"¿Cuál es la diferencia entre una clase y un objeto?","options":["Son exactamente lo mismo","La clase es el molde/plantilla; el objeto es una instancia real creada a partir de ese molde","El objeto es el molde; la clase es la instancia","Una clase solo puede crear un objeto"],"correctIndex":1},"comments":[]},{"id":"poo-03","order":3,"type":"text","title":"Encapsulamiento: proteger el estado interno","description":"Por qué \"esconder\" datos a propósito es una buena práctica, no un secreto sin sentido.","content":"<h2>El problema sin encapsulamiento</h2><p>Si cualquier parte del código puede modificar directamente cualquier propiedad de un objeto, sin restricciones, es fácil dejar el objeto en un estado inválido — por ejemplo, poner la \"energía\" de un personaje en -500, algo que no debería ser posible.</p><h2>La idea del encapsulamiento</h2><p>El <strong>encapsulamiento</strong> restringe el acceso directo a ciertos datos internos de un objeto, exponiendo solo métodos controlados para modificarlos — esos métodos pueden validar que el cambio tenga sentido antes de aplicarlo.</p><div class=\"example\">🧪 <code>class Personaje {<br>&nbsp;&nbsp;#energia = 100 // privado, no accesible desde afuera<br>&nbsp;&nbsp;perderEnergia(cantidad) {<br>&nbsp;&nbsp;&nbsp;&nbsp;this.#energia = Math.max(0, this.#energia - cantidad) // nunca baja de 0<br>&nbsp;&nbsp;}<br>}</code><br>Nadie desde afuera puede poner <code>#energia</code> en un número negativo directamente — solo pueden pasar por <code>perderEnergia()</code>, que garantiza que el valor se mantenga válido.</div><div class=\"tip\">💡 Es la misma idea de \"interfaz pública vs. detalles internos\" que viste en el curso de Principios SOLID (Inversión de Dependencias e Interface Segregation) — encapsulamiento es cómo POO implementa ese principio a nivel de un solo objeto.</div>","exercises":[{"id":"poo-03-1","type":"challenge","prompt":"Piensa en un objeto del mundo real con un \"estado protegido\" (por ejemplo, no puedes poner tu cuenta bancaria en un balance negativo arbitrario sin pasar por un proceso). Relaciónalo con el concepto de encapsulamiento. Compártelo con tu mascota.","solution":""}],"resources":[],"quiz":{"question":"¿Qué problema busca evitar el encapsulamiento?","options":["Que el código sea más lento","Que cualquier parte del código deje un objeto en un estado inválido, modificando datos sin control","Que se puedan crear clases","Que los objetos tengan métodos"],"correctIndex":1},"comments":[]},{"id":"poo-04","order":4,"type":"text","title":"Herencia: reutilizar y extender comportamiento","description":"Cómo evitar repetir código entre clases que comparten características.","content":"<h2>El problema que resuelve</h2><p>Si tienes clases <code>Perro</code> y <code>Gato</code> que comparten propiedades (nombre, energía) y métodos (comer, dormir), copiar y pegar ese código en ambas clases viola el principio de \"no te repitas\" que viste en Fundamentos de Programación.</p><h2>La solución: una clase base compartida</h2><div class=\"example\">🧪 <code>class Animal {<br>&nbsp;&nbsp;constructor(nombre) { this.nombre = nombre }<br>&nbsp;&nbsp;dormir() { return this.nombre + \" está durmiendo\" }<br>}<br><br>class Perro extends Animal {<br>&nbsp;&nbsp;ladrar() { return this.nombre + \" dice: ¡Guau!\" }<br>}<br><br>class Gato extends Animal {<br>&nbsp;&nbsp;maullar() { return this.nombre + \" dice: ¡Miau!\" }<br>}<br><br>const rex = new Perro(\"Rex\")<br>rex.dormir()  // heredado de Animal, funciona sin repetir código<br>rex.ladrar()  // propio de Perro</code></div><p><code>Perro</code> y <code>Gato</code> <strong>heredan</strong> de <code>Animal</code> — obtienen automáticamente sus propiedades y métodos, y solo agregan lo que las hace específicas.</p><div class=\"warn\">⚠️ Recuerda el Principio de Sustitución de Liskov del curso de SOLID: la herencia debe usarse solo cuando el subtipo realmente cumple TODAS las promesas del tipo base — heredar solo para \"ahorrar código\" sin que la relación \"es-un\" tenga sentido real suele causar problemas más adelante.</div>","exercises":[{"id":"poo-04-1","type":"challenge","prompt":"Diseña una clase base y dos clases que hereden de ella, compartiendo al menos un método heredado y agregando cada una algo propio (puede ser el ejemplo de animales u otro de tu elección). Comparte tu diseño con tu mascota.","solution":""}],"resources":[],"quiz":{"question":"¿Qué problema resuelve la herencia entre clases?","options":["Hacer el código más lento a propósito","Evitar repetir propiedades y métodos compartidos entre clases relacionadas","Eliminar la necesidad de objetos","Ocultar todos los datos de una clase"],"correctIndex":1},"comments":[]},{"id":"poo-05","order":5,"type":"text","title":"Polimorfismo: una interfaz, muchas formas","description":"Cómo tratar objetos distintos de forma uniforme, aunque se comporten diferente por dentro.","content":"<h2>La idea central</h2><p><strong>Polimorfismo</strong> (del griego, \"muchas formas\") significa que objetos de clases distintas pueden responder al MISMO método de formas diferentes, cada uno según su propia implementación.</p><div class=\"example\">🧪 <code>class Perro extends Animal {<br>&nbsp;&nbsp;sonido() { return \"¡Guau!\" }<br>}<br>class Gato extends Animal {<br>&nbsp;&nbsp;sonido() { return \"¡Miau!\" }<br>}<br><br>const animales = [new Perro(\"Rex\"), new Gato(\"Luna\")]<br>for (const animal of animales) {<br>&nbsp;&nbsp;console.log(animal.sonido()) // \"¡Guau!\", luego \"¡Miau!\"<br>}</code><br>El código que recorre la lista llama a <code>.sonido()</code> de la misma forma para todos, sin necesitar saber si es un perro o un gato — cada objeto \"sabe\" cómo responder a su manera.</div><h2>Por qué importa: código que no necesita cambiar al agregar casos nuevos</h2><p>Si mañana agregas una clase <code>Pajaro</code> con su propio <code>sonido()</code>, el código que recorre la lista de animales NO necesita cambiar en absoluto — sigue funcionando igual. Es el mismo espíritu del Principio Abierto/Cerrado que viste en SOLID.</p><div class=\"tip\">💡 El polimorfismo es lo que hace posible escribir código genérico (\"para cada animal, haz que suene\") sin un gigantesco <code>if/else</code> revisando de qué tipo específico es cada objeto.</div>","exercises":[{"id":"poo-05-1","type":"challenge","prompt":"Agrega una tercera clase (por ejemplo \"Pajaro\") a tu diseño del módulo anterior, con su propia versión de un método compartido, y explica por qué el código que recorre la lista de animales no necesitaría cambiar. Comparte con tu mascota.","solution":""}],"resources":[],"quiz":{"question":"¿Qué demuestra el polimorfismo en el ejemplo de animales y sonidos?","options":["Que todos los animales deben sonar igual","Que objetos de clases distintas pueden responder al mismo método, cada uno a su manera","Que la herencia es innecesaria","Que no se pueden usar listas de objetos"],"correctIndex":1},"comments":[]},{"id":"poo-06","order":6,"type":"text","title":"Abstracción y cuándo NO usar POO","description":"Cierre del curso: el último pilar, y un poco de honestidad sobre los límites del paradigma.","content":"<h2>Abstracción: mostrar solo lo esencial</h2><p>La <strong>abstracción</strong> es exponer una interfaz simple hacia afuera, mientras se esconde la complejidad interna de cómo se logra. Cuando llamas a <code>auto.arrancar()</code>, no necesitas saber los detalles del motor de combustión o eléctrico por dentro — la clase abstrae esa complejidad detrás de un método simple.</p><h2>Los cuatro pilares, juntos</h2><ul><li><strong>Encapsulamiento:</strong> proteger el estado interno.</li><li><strong>Herencia:</strong> reutilizar y extender comportamiento compartido.</li><li><strong>Polimorfismo:</strong> tratar objetos distintos de forma uniforme.</li><li><strong>Abstracción:</strong> exponer solo lo necesario, esconder el resto.</li></ul><h2>Cuándo POO NO es la mejor herramienta</h2><div class=\"warn\">⚠️ POO no es universalmente \"la forma correcta\" de programar — para transformaciones simples de datos, muchos programadores prefieren un estilo funcional (como viste de pasada en React). Forzar jerarquías de clases elaboradas para un script pequeño es sobre-ingeniería, el mismo problema que viste con SOLID aplicado de más.</div><h2>Cierre del curso</h2><div class=\"tip\">💡 Con esto completas un recorrido por los 4 pilares de POO: qué es un objeto, clases vs. instancias, encapsulamiento, herencia, polimorfismo y abstracción — y, tan importante como todo lo anterior, cuándo NO es la herramienta correcta. El curso de Paradigmas de la Programación te va a mostrar cómo POO se compara con otros estilos, para que puedas elegir con criterio, no por costumbre.</div>","exercises":[{"id":"poo-06-1","type":"challenge","prompt":"De los 4 pilares de POO (encapsulamiento, herencia, polimorfismo, abstracción), ¿cuál te parece más útil para el tipo de programas que te gustaría construir? Justifica tu respuesta y compártela con tu mascota.","solution":""}],"resources":[],"quiz":{"question":"¿Qué es la abstracción en POO?","options":["Eliminar todos los métodos de una clase","Exponer una interfaz simple hacia afuera, escondiendo la complejidad interna","Es sinónimo exacto de herencia","Solo aplica a lenguajes funcionales"],"correctIndex":1},"comments":[]}]'::jsonb),
  ('course-paradigmas-programacion', 'Paradigmas de la Programación: Imperativo, POO, Funcional y Más', 'Un recorrido comparativo por los grandes estilos de programación — para entender POR QUÉ existen distintas formas de escribir código, no solo memorizar sintaxis.', 'Eres el Mago, tutor de Paradigmas de la Programación en Oliver Academy. Este curso es comparativo — usa el MISMO ejemplo (ej. sumar una lista de números) resuelto en distintos paradigmas cuando sea posible, para que la diferencia sea concreta y visible, no abstracta.', '🎭', '#fb7185', 'Programación', 'Paradigmas', null, false, '[{"id":"para-01","order":1,"type":"text","title":"¿Qué es un paradigma de programación?","description":"Una forma fundamental de pensar un problema, no solo una sintaxis distinta.","content":"<h2>Más que sintaxis</h2><p>Un <strong>paradigma de programación</strong> es un enfoque fundamental para estructurar y pensar la solución de un problema — determina cómo organizas el código, cómo manejas el estado, y qué preguntas te haces al diseñar una solución.</p><h2>El mismo problema, distintas formas de pensarlo</h2><p>Sumar una lista de números se puede resolver con un bucle que acumula un total paso a paso (imperativo), con un objeto <code>Calculadora</code> que sabe sumar sus propios números (orientado a objetos), o con una función que combina la lista sin variables intermedias mutables (funcional) — el RESULTADO es el mismo, pero la forma de razonar el problema es distinta en cada caso.</p><div class=\"tip\">💡 Este curso va a resolver el mismo puñado de problemas de ejemplo en varios paradigmas distintos, para que la diferencia se sienta concreta — no es solo teoría abstracta, cada paradigma realmente cambia cómo escribes y piensas el código.</div><div class=\"warn\">⚠️ Ningún paradigma es \"el mejor\" en abstracto — cada uno tiene problemas para los que encaja naturalmente, y otros para los que se siente forzado. La meta de este curso es que puedas reconocer cuál usar, no que adoptes uno como dogma.</div>","exercises":[{"id":"para-01-1","type":"challenge","prompt":"Piensa en un problema simple (ordenar una lista de tareas, calcular un promedio) y describe brevemente cómo lo resolverías \"paso a paso\" (más imperativo) vs. describiendo \"qué resultado quieres\" (más declarativo). Compártelo con tu mascota.","solution":""}],"resources":[],"quiz":{"question":"¿Qué determina principalmente un paradigma de programación?","options":["Solo el color del editor de código","Un enfoque fundamental para pensar y estructurar la solución de un problema","El nombre del lenguaje que usas","La velocidad de ejecución únicamente"],"correctIndex":1},"comments":[]},{"id":"para-02","order":2,"type":"text","title":"Paradigma imperativo y procedural","description":"El más cercano a cómo funciona realmente la máquina: instrucciones paso a paso.","content":"<h2>La idea central</h2><p>El paradigma <strong>imperativo</strong> describe la solución como una secuencia explícita de instrucciones que modifican el estado del programa paso a paso — es el estilo más directo, y el que probablemente ya usaste en el curso de Fundamentos de Programación.</p><div class=\"example\">🧪 <code>let total = 0<br>for (const n of numeros) {<br>&nbsp;&nbsp;total = total + n<br>}</code><br>Cada paso modifica explícitamente la variable <code>total</code>, siguiendo instrucciones literales una por una.</div><h2>Procedural: imperativo organizado en funciones</h2><p>El estilo <strong>procedural</strong> es imperativo, pero organiza el código en funciones reutilizables (procedimientos) en vez de un solo bloque largo de instrucciones — un paso hacia mejor organización, sin llegar todavía a objetos o funciones puras.</p><h2>Ventajas y límites</h2><div class=\"tip\">💡 El estilo imperativo es intuitivo y cercano a cómo realmente ejecuta instrucciones un procesador — pero en programas grandes, el estado que cambia constantemente en muchos lugares distintos puede volverse difícil de rastrear, uno de los problemas que otros paradigmas buscan resolver de formas distintas.</div>","exercises":[{"id":"para-02-1","type":"challenge","prompt":"Escribe en pseudocódigo, de forma puramente imperativa (con un bucle y una variable que se modifica paso a paso), una solución para encontrar el número mayor en una lista. Comparte tu código con tu mascota.","solution":""}],"resources":[],"quiz":{"question":"¿Qué caracteriza al paradigma imperativo?","options":["Describir solo el resultado deseado","Una secuencia explícita de instrucciones que modifican el estado paso a paso","Evitar completamente el uso de variables","Solo puede usarse en lenguajes funcionales"],"correctIndex":1},"comments":[]},{"id":"para-03","order":3,"type":"text","title":"Paradigma orientado a objetos","description":"Modelar el problema como \"cosas\" con datos y comportamiento propio.","content":"<h2>Repaso rápido (viste esto a fondo en el curso de POO)</h2><p>El paradigma <strong>orientado a objetos</strong> organiza el código alrededor de objetos que combinan datos y comportamiento — en vez de tener funciones sueltas operando sobre datos genéricos, cada \"cosa\" relevante del problema se modela como un objeto con su propia identidad.</p><div class=\"example\">🧪 El mismo problema de sumar números, en un estilo orientado a objetos:<br><code>class Acumulador {<br>&nbsp;&nbsp;#total = 0<br>&nbsp;&nbsp;sumar(n) { this.#total += n; return this }<br>&nbsp;&nbsp;obtenerTotal() { return this.#total }<br>}<br><br>const acc = new Acumulador()<br>numeros.forEach(n => acc.sumar(n))<br>acc.obtenerTotal()</code></div><h2>Cuándo este paradigma encaja naturalmente</h2><p>POO tiende a encajar bien cuando el problema tiene \"cosas\" claras con estado propio e identidad que persiste en el tiempo (un usuario, un pedido, un personaje de videojuego) — menos naturalmente cuando el problema es principalmente transformar datos de un formato a otro.</p><div class=\"tip\">💡 Si el curso completo de POO fue un edificio, este módulo es solo el resumen del plano — vuelve a ese curso si necesitas repasar clases, herencia, encapsulamiento o polimorfismo con más profundidad.</div>","exercises":[{"id":"para-03-1","type":"challenge","prompt":"Compara el código orientado a objetos de este módulo con el código imperativo del módulo anterior, ambos resolviendo \"sumar números\". ¿Cuál se siente más natural para ti? Justifica y comparte con tu mascota.","solution":""}],"resources":[],"quiz":{"question":"¿Cuándo tiende a encajar naturalmente el paradigma orientado a objetos?","options":["Solo para cálculos matemáticos simples","Cuando el problema tiene \"cosas\" con estado propio e identidad que persiste en el tiempo","Nunca es recomendable usarlo","Solo en lenguajes funcionales"],"correctIndex":1},"comments":[]},{"id":"para-04","order":4,"type":"text","title":"Paradigma funcional: computar sin mutar estado","description":"Resolver problemas combinando funciones puras, evitando cambiar datos existentes.","content":"<h2>La idea central</h2><p>El paradigma <strong>funcional</strong> trata la computación como la evaluación de funciones matemáticas — favorece <strong>funciones puras</strong> (mismo input, mismo output, sin efectos secundarios) e <strong>inmutabilidad</strong> (crear datos nuevos en vez de modificar los existentes), como viste en el curso de El Paradigma de Oliver Academy (React).</p><div class=\"example\">🧪 El mismo problema de sumar números, en estilo funcional:<br><code>const total = numeros.reduce((acumulado, n) => acumulado + n, 0)</code><br>Sin bucle explícito, sin variable que se modifica paso a paso — <code>reduce</code> combina la lista completa en un solo valor, describiendo QUÉ operación combinar, no CÓMO iterar manualmente.</div><h2>Por qué evitar mutación</h2><p>Cuando ninguna función modifica datos existentes fuera de sí misma, es mucho más fácil predecir el comportamiento del código — no hay que preguntarse \"¿quién más está usando y quizás modificando estos datos ahora mismo?\".</p><div class=\"tip\">💡 Funciones como <code>map</code>, <code>filter</code> y <code>reduce</code> (que probablemente ya usaste sin llamarlo \"programación funcional\") son herramientas centrales de este paradigma — transforman una lista en otra nueva, sin tocar la original.</div>","exercises":[{"id":"para-04-1","type":"challenge","prompt":"Reescribe el problema de \"encontrar el número mayor en una lista\" (del módulo de imperativo) usando un estilo funcional, con reduce o alguna función similar. Comparte ambas versiones (imperativa y funcional) con tu mascota.","solution":""}],"resources":[],"quiz":{"question":"¿Qué evita típicamente el paradigma funcional?","options":["El uso de funciones","Mutar (modificar) datos existentes — prefiere crear datos nuevos","Los bucles bajo cualquier circunstancia","Los números"],"correctIndex":1},"comments":[]},{"id":"para-05","order":5,"type":"text","title":"Paradigma declarativo: el \"qué\" en vez del \"cómo\"","description":"SQL, HTML y React comparten algo en común que no siempre es obvio.","content":"<h2>Un paraguas más amplio que \"funcional\"</h2><p>Lo <strong>declarativo</strong> describe el resultado deseado sin especificar los pasos exactos para lograrlo — el paradigma funcional es una forma de ser declarativo, pero el concepto es más amplio.</p><h2>Ejemplos que ya conoces, bajo un mismo paraguas</h2><ul><li><strong>SQL</strong> (curso de Bases de Datos): <code>SELECT nombre FROM estudiantes WHERE edad > 16</code> — describes QUÉ datos quieres, no cómo recorrer la tabla fila por fila.</li><li><strong>HTML/CSS:</strong> describes cómo se debe VER algo, no los pasos de dibujo pixel por pixel.</li><li><strong>React (JSX):</strong> describes cómo se debe ver la interfaz para un estado dado, no los pasos para actualizar el DOM manualmente.</li></ul><div class=\"example\">🧪 <strong>Imperativo:</strong> \"ve a la cocina, abre el refrigerador, toma la leche, ciérralo, sírvela en un vaso.\"<br><strong>Declarativo:</strong> \"quiero un vaso de leche\" — no te importa cómo se logra, solo el resultado.</div><div class=\"tip\">💡 Reconocer este patrón compartido entre SQL, HTML y React ayuda a entender por qué, aunque parezcan tecnologías totalmente distintas, se \"sienten\" parecidas de cierta forma — todas comparten la misma filosofía declarativa de fondo.</div>","exercises":[{"id":"para-05-1","type":"challenge","prompt":"Identifica otro ejemplo de tu vida (tecnológico o no) que sea \"declarativo\" — donde describes el resultado sin especificar los pasos exactos. Compártelo con tu mascota.","solution":""}],"resources":[],"quiz":{"question":"¿Qué tienen en común SQL, HTML y JSX de React según este módulo?","options":["Todos son el mismo lenguaje","Los tres son declarativos: describen el resultado deseado, no los pasos exactos","Ninguno permite variables","Solo sirven para bases de datos"],"correctIndex":1},"comments":[]},{"id":"para-06","order":6,"type":"text","title":"Multiparadigma: por qué los lenguajes modernos mezclan estilos","description":"Cierre del curso: la pregunta correcta nunca es \"cuál paradigma es el mejor\".","content":"<h2>Pocos lenguajes modernos son \"puros\" en un solo paradigma</h2><p>JavaScript, Python, e incluso Java moderno permiten mezclar estilos imperativo, orientado a objetos y funcional en el mismo programa — la línea entre paradigmas, en la práctica diaria, es mucho más borrosa que en la teoría de un curso.</p><h2>Cómo elegir en la práctica</h2><ul><li>Para transformar/filtrar datos: el estilo funcional (<code>map</code>, <code>filter</code>, <code>reduce</code>) suele ser más claro y compacto.</li><li>Para modelar \"cosas\" con estado propio que persiste (un usuario, un carrito de compras): POO suele encajar naturalmente.</li><li>Para lógica de control simple y directa: el estilo imperativo básico sigue siendo perfectamente válido, sin necesitar sofisticación adicional.</li></ul><div class=\"warn\">⚠️ Forzar TODO un programa a un solo paradigma \"por pureza\" casi siempre produce código más difícil de leer que simplemente usar la herramienta natural para cada parte del problema.</div><h2>Cierre del curso</h2><div class=\"tip\">💡 Con esto completas un recorrido comparativo por los grandes paradigmas: imperativo/procedural, orientado a objetos, funcional, y declarativo — y la idea multiparadigma que los conecta en la práctica real. La habilidad que de verdad importa no es \"dominar un paradigma\" — es reconocer cuál forma de pensar encaja mejor con CADA parte específica de un problema, y poder combinarlas con criterio.</div>","exercises":[{"id":"para-06-1","type":"challenge","prompt":"Piensa en un proyecto (real o hipotético) que te gustaría construir, e identifica qué parte usarías con estilo funcional, cuál con POO, y cuál simplemente imperativo. Comparte tu análisis con tu mascota.","solution":""}],"resources":[],"quiz":{"question":"Según el cierre de este curso, ¿cuál es la habilidad que realmente importa sobre los paradigmas?","options":["Memorizar la definición exacta de cada uno","Reconocer cuál forma de pensar encaja mejor con cada parte de un problema, y poder combinarlas","Usar siempre el mismo paradigma en todo proyecto","Evitar el paradigma orientado a objetos siempre"],"correctIndex":1},"comments":[]}]'::jsonb),
  ('course-react', 'React: De Cero a Aplicaciones Reales', 'Componentes, props, estado, efectos, listas y formularios — un curso completo y autocontenido de React, la librería con la que está construida esta misma plataforma.', 'Eres el Mago, tutor del curso de React en Oliver Academy. A diferencia del curso "El Paradigma de Oliver Academy" (que explica el paradigma declarativo usando esta app como ejemplo), este curso es una introducción completa y autocontenida a React como habilidad — cubre lo necesario para construir una app propia desde cero. Usa ejemplos de código cortos y prácticos.', '⚛️', '#61dafb', 'Programación', 'Frontend Moderno', null, false, '[{"id":"react2-01","order":1,"type":"text","title":"¿Por qué React? El problema que resuelve","description":"De manipular el DOM a mano a describir interfaces declarativamente.","content":"<h2>El problema antes de frameworks modernos</h2><p>Sin una librería como React, construir una interfaz interactiva significaba manipular el DOM manualmente — crear elementos, actualizar su contenido, y sobre todo, mantener sincronizado \"lo que se ve\" con \"los datos actuales\" cada vez que algo cambiaba. En apps grandes, esto se volvía propenso a errores y difícil de mantener.</p><h2>La solución de React: la interfaz como función del estado</h2><p>React propone: describe cómo se debe ver la interfaz PARA UN ESTADO DADO, y deja que React se encargue de actualizar el DOM real cuando ese estado cambia — no tienes que escribir manualmente los pasos de \"qué cambiar\".</p><div class=\"tip\">💡 Si ya tomaste el curso de El Paradigma de Oliver Academy, este principio te resultará familiar — aquí lo vas a aplicar construyendo componentes propios desde cero, no solo analizando cómo está hecha esta plataforma.</div><h2>¿Por qué es tan popular?</h2><p>React (creado por Facebook/Meta en 2013) popularizó este enfoque, con un ecosistema enorme de herramientas y una comunidad masiva — hoy es una de las habilidades más buscadas en desarrollo web frontend.</p>","exercises":[{"id":"react2-01-1","type":"challenge","prompt":"Describe con tus palabras la diferencia entre \"manipular el DOM paso a paso\" y \"describir cómo se ve la interfaz para un estado dado\". Compártelo con tu mascota.","solution":""}],"resources":[],"quiz":{"question":"¿Qué propone React como enfoque central?","options":["Manipular el DOM manualmente en cada cambio","Describir la interfaz para un estado dado, dejando que React actualice el DOM","Evitar completamente el uso de JavaScript","Reemplazar HTML por completo"],"correctIndex":1},"comments":[]},{"id":"react2-02","order":2,"type":"text","title":"Tu primer componente: JSX y props","description":"La unidad básica de construcción de cualquier app en React.","content":"<h2>Un componente es una función que devuelve interfaz</h2><div class=\"example\">🧪 <code>function Saludo({ nombre }) {<br>&nbsp;&nbsp;return &lt;h1&gt;Hola, {nombre}!&lt;/h1&gt;<br>}<br><br>&lt;Saludo nombre=\"Ana\" /&gt;</code></div><p>Este componente <code>Saludo</code> recibe <strong>props</strong> (los datos que le pasas, como <code>nombre</code>) y devuelve JSX — la sintaxis que mezcla HTML y JavaScript.</p><h2>Props: solo lectura</h2><p>Las props que recibe un componente son de <strong>solo lectura</strong> — un componente nunca debe modificar sus propias props directamente; si necesita cambiar algo, eso es trabajo del <strong>estado</strong> (siguiente módulo).</p><h2>Composición: componentes dentro de componentes</h2><div class=\"example\">🧪 <code>function App() {<br>&nbsp;&nbsp;return (<br>&nbsp;&nbsp;&nbsp;&nbsp;&lt;div&gt;<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&lt;Saludo nombre=\"Ana\" /&gt;<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&lt;Saludo nombre=\"Luis\" /&gt;<br>&nbsp;&nbsp;&nbsp;&nbsp;&lt;/div&gt;<br>&nbsp;&nbsp;)<br>}</code><br>Un componente padre (<code>App</code>) usa el componente <code>Saludo</code> dos veces, con props distintas — la reutilización es exactamente el punto.</div>","exercises":[{"id":"react2-02-1","type":"challenge","prompt":"Escribe un componente propio (en pseudocódigo o JSX real) que reciba 2 props y las use dentro de su JSX. Comparte tu componente con tu mascota.","solution":""}],"resources":[],"quiz":{"question":"¿Qué tipo de acceso tiene un componente sobre las props que recibe?","options":["Puede modificarlas libremente","Solo lectura — no debe modificarlas directamente","No puede leerlas, solo pasarlas","Las props no existen en React"],"correctIndex":1},"comments":[]},{"id":"react2-03","order":3,"type":"text","title":"Estado con useState","description":"Componentes que recuerdan información y cambian en respuesta a interacciones.","content":"<h2>useState: la memoria de un componente</h2><div class=\"example\">🧪 <code>function Contador() {<br>&nbsp;&nbsp;const [cuenta, setCuenta] = useState(0)<br>&nbsp;&nbsp;return (<br>&nbsp;&nbsp;&nbsp;&nbsp;&lt;button onClick={() =&gt; setCuenta(cuenta + 1)}&gt;<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Clics: {cuenta}<br>&nbsp;&nbsp;&nbsp;&nbsp;&lt;/button&gt;<br>&nbsp;&nbsp;)<br>}</code></div><p><code>useState(0)</code> devuelve dos cosas: el valor actual (<code>cuenta</code>) y una función para actualizarlo (<code>setCuenta</code>). Llamar a <code>setCuenta</code> le dice a React \"este componente cambió, vuelve a renderizarlo\" — no modificas <code>cuenta</code> directamente.</h2><h2>Cada componente tiene su propio estado independiente</h2><p>Si usas <code>&lt;Contador /&gt;</code> dos veces en la misma pantalla, cada instancia mantiene su propio valor de <code>cuenta</code>, completamente independiente de la otra.</p><div class=\"warn\">⚠️ Nunca modifiques el estado directamente (<code>cuenta = cuenta + 1</code>) — React no se entera de ese cambio y la interfaz no se actualiza. Siempre usa la función setter (<code>setCuenta</code>).</div><div class=\"tip\">💡 Este mismo patrón — <code>useState</code> para lo que un componente recuerda por sí mismo — es la base de casi cualquier interacción interactiva en React: formularios, menús desplegables, pestañas activas, y mucho más.</div>","exercises":[{"id":"react2-03-1","type":"challenge","prompt":"Diseña un componente con useState que maneje un booleano (por ejemplo, \"mostrar\" / \"ocultar\" algo) con un botón que lo alterne. Comparte tu código con tu mascota.","solution":""}],"resources":[],"quiz":{"question":"¿Qué pasa si modificas el estado directamente en vez de usar la función setter (por ejemplo, cuenta = cuenta + 1)?","options":["Funciona exactamente igual","React no se entera del cambio y la interfaz no se actualiza","La app se cierra automáticamente","Es la forma recomendada de hacerlo"],"correctIndex":1},"comments":[]},{"id":"react2-04","order":4,"type":"text","title":"Efectos secundarios con useEffect","description":"Cómo sincronizar un componente con algo externo: una petición, un temporizador, una suscripción.","content":"<h2>¿Qué es un \"efecto secundario\"?</h2><p>Renderizar JSX a partir de props/estado es el trabajo \"puro\" de un componente. Cualquier cosa que interactúe con el mundo exterior — pedir datos a un servidor, activar un temporizador, suscribirse a un evento — es un <strong>efecto secundario</strong>, y React lo maneja con el hook <code>useEffect</code>.</p><div class=\"example\">🧪 <code>function PerfilUsuario({ userId }) {<br>&nbsp;&nbsp;const [usuario, setUsuario] = useState(null)<br>&nbsp;&nbsp;useEffect(() =&gt; {<br>&nbsp;&nbsp;&nbsp;&nbsp;fetchUsuario(userId).then(setUsuario)<br>&nbsp;&nbsp;}, [userId]) // se re-ejecuta si userId cambia<br>&nbsp;&nbsp;return usuario ? &lt;p&gt;{usuario.nombre}&lt;/p&gt; : &lt;p&gt;Cargando…&lt;/p&gt;<br>}</code></div><h2>El array de dependencias</h2><p>El segundo argumento de <code>useEffect</code> (<code>[userId]</code>) le dice a React CUÁNDO volver a ejecutar el efecto — solo cuando alguno de esos valores cambie entre renders. Un array vacío <code>[]</code> significa \"solo una vez, al montar el componente\".</p><div class=\"warn\">⚠️ Omitir el array de dependencias hace que el efecto se ejecute en CADA render — casi siempre un error, especialmente si el efecto hace una petición de red (podría disparar peticiones infinitas).</div><div class=\"tip\">💡 Este mismo patrón — pedir datos al montar un componente — es exactamente cómo esta plataforma carga, por ejemplo, tus tareas o tu progreso al abrir el Dashboard.</div>","exercises":[{"id":"react2-04-1","type":"challenge","prompt":"Diseña (en pseudocódigo) un componente que use useEffect para pedir datos cuando cambie una prop específica, incluyendo el array de dependencias correcto. Comparte con tu mascota.","solution":""}],"resources":[],"quiz":{"question":"¿Qué controla el array de dependencias de useEffect?","options":["El color del componente","Cuándo se vuelve a ejecutar el efecto — solo cuando cambian esos valores","Cuántas veces se puede usar el componente","No tiene ningún efecto real"],"correctIndex":1},"comments":[]},{"id":"react2-05","order":5,"type":"text","title":"Listas, keys y renderizado condicional","description":"Cómo mostrar colecciones de datos y decidir qué mostrar según el estado.","content":"<h2>Renderizar listas con map</h2><div class=\"example\">🧪 <code>function ListaTareas({ tareas }) {<br>&nbsp;&nbsp;return (<br>&nbsp;&nbsp;&nbsp;&nbsp;&lt;ul&gt;<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;{tareas.map(t =&gt; (<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&lt;li key={t.id}&gt;{t.titulo}&lt;/li&gt;<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;))}<br>&nbsp;&nbsp;&nbsp;&nbsp;&lt;/ul&gt;<br>&nbsp;&nbsp;)<br>}</code></div><h2>¿Por qué la \"key\" es obligatoria?</h2><p>La prop <code>key</code> le da a React un identificador estable para cada elemento de la lista, permitiéndole saber exactamente cuál cambió, se agregó o se eliminó entre renders — sin ella, React puede confundirse y actualizar el elemento equivocado.</p><div class=\"warn\">⚠️ Usar el índice del array como key (<code>key={indice}</code>) funciona para listas estáticas, pero causa bugs sutiles en listas que se reordenan o filtran — siempre que exista, usa un id único y estable del propio dato.</div><h2>Renderizado condicional</h2><div class=\"example\">🧪 <code>{tareas.length === 0 ? (<br>&nbsp;&nbsp;&lt;p&gt;No hay tareas&lt;/p&gt;<br>) : (<br>&nbsp;&nbsp;&lt;ListaTareas tareas={tareas} /&gt;<br>)}</code><br>El operador ternario dentro de las llaves decide, en tiempo de render, qué JSX mostrar según el estado actual.</div>","exercises":[{"id":"react2-05-1","type":"challenge","prompt":"Diseña un componente que reciba una lista de objetos con id y renderice cada uno con su key correcta, más un renderizado condicional para cuando la lista esté vacía. Comparte tu código con tu mascota.","solution":""}],"resources":[],"quiz":{"question":"¿Para qué sirve la prop \"key\" al renderizar una lista?","options":["Solo es decorativa, no afecta nada","Le da a React un identificador estable para saber qué elemento cambió, se agregó o eliminó","Sirve para ordenar la lista automáticamente","Es obligatoria solo en listas vacías"],"correctIndex":1},"comments":[]},{"id":"react2-06","order":6,"type":"text","title":"Formularios controlados","description":"Cómo React mantiene sincronizado lo que el usuario escribe con el estado del componente.","content":"<h2>El patrón de \"componente controlado\"</h2><div class=\"example\">🧪 <code>function FormularioLogin() {<br>&nbsp;&nbsp;const [email, setEmail] = useState('''')<br>&nbsp;&nbsp;return (<br>&nbsp;&nbsp;&nbsp;&nbsp;&lt;input<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;value={email}<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;onChange={(e) =&gt; setEmail(e.target.value)}<br>&nbsp;&nbsp;&nbsp;&nbsp;/&gt;<br>&nbsp;&nbsp;)<br>}</code></div><p>El valor del input SIEMPRE viene del estado (<code>value={email}</code>), y cada tecleo actualiza ese estado (<code>onChange</code>) — el estado de React es la \"fuente de verdad\", no el DOM del input por sí mismo. Por eso se llama \"controlado\".</p><h2>Manejar el envío del formulario</h2><div class=\"example\">🧪 <code>function manejarEnvio(e) {<br>&nbsp;&nbsp;e.preventDefault() // evita que el navegador recargue la página<br>&nbsp;&nbsp;console.log(email)<br>}<br>&lt;form onSubmit={manejarEnvio}&gt;...&lt;/form&gt;</code></div><div class=\"tip\">💡 <code>e.preventDefault()</code> es esencial: sin él, el navegador intentaría hacer una recarga completa de página al enviar el formulario, exactamente lo que React está diseñado para evitar.</div><h2>Múltiples campos con un solo estado (objeto)</h2><p>Para formularios con muchos campos, es común usar un solo objeto de estado (<code>{ email, password }</code>) en vez de un <code>useState</code> por cada campo, actualizándolo de forma inmutable con el spread operator (<code>{...datos, email: nuevoValor}</code>) — el mismo principio de inmutabilidad que ya conoces.</p>","exercises":[{"id":"react2-06-1","type":"challenge","prompt":"Diseña un formulario controlado con 2 campos usando un solo objeto de estado, incluyendo el manejo del envío con preventDefault. Comparte tu código con tu mascota.","solution":""}],"resources":[],"quiz":{"question":"¿Por qué se llama \"controlado\" a un input cuyo valor viene del estado de React?","options":["Porque el usuario no puede escribir en él","Porque el estado de React es la fuente de verdad del valor, no el DOM del input por sí mismo","Porque solo funciona con contraseñas","Porque React bloquea el teclado"],"correctIndex":1},"comments":[]},{"id":"react2-07","order":7,"type":"text","title":"Enrutamiento: navegar entre páginas sin recargar","description":"Cierre del curso: cómo una app de una sola página simula tener varias \"páginas\".","content":"<h2>El problema: una sola página HTML, muchas \"pantallas\"</h2><p>Una app de React típicamente carga UN solo archivo HTML — pero el usuario espera navegar entre \"páginas\" (inicio, perfil, configuración) sin que el navegador recargue completamente cada vez. Un <strong>enrutador</strong> (como React Router) resuelve esto en el cliente.</p><h2>Rutas básicas</h2><div class=\"example\">🧪 <code>&lt;Routes&gt;<br>&nbsp;&nbsp;&lt;Route path=\"/\" element={&lt;Inicio /&gt;} /&gt;<br>&nbsp;&nbsp;&lt;Route path=\"/perfil\" element={&lt;Perfil /&gt;} /&gt;<br>&lt;/Routes&gt;</code><br>Cada <code>Route</code> asocia una URL con el componente que se debe mostrar — cuando la URL coincide, React renderiza ese componente, sin recargar la página.</h2><h2>Navegación sin recarga</h2><div class=\"example\">🧪 <code>&lt;Link to=\"/perfil\"&gt;Ir a mi perfil&lt;/Link&gt;</code><br>A diferencia de una etiqueta <code>&lt;a&gt;</code> normal, <code>&lt;Link&gt;</code> intercepta el clic y cambia la URL/vista usando JavaScript, sin la recarga completa que haría un enlace HTML tradicional.</div><h2>Cierre del curso</h2><div class=\"tip\">💡 Con esto completas un curso completo de React: por qué existe, componentes y props, estado con useState, efectos con useEffect, listas con keys, formularios controlados, y finalmente enrutamiento entre \"páginas\". Con estas piezas ya tienes la base real para construir una aplicación interactiva completa desde cero — exactamente el mismo conjunto de herramientas con el que está construida esta plataforma que estás usando ahora mismo.</div>","exercises":[{"id":"react2-07-1","type":"challenge","prompt":"Diseña (en pseudocódigo) 3 rutas para una app hipotética tuya, con sus componentes correspondientes, y un menú de navegación usando Link para moverse entre ellas. Comparte tu diseño con tu mascota.","solution":""}],"resources":[],"quiz":{"question":"¿Qué diferencia a <Link> de una etiqueta <a> normal en una app de React con enrutamiento?","options":["No hay ninguna diferencia","<Link> cambia la vista con JavaScript, sin la recarga completa de página que haría un <a> normal","<Link> solo funciona en el servidor","<a> es más rápido siempre"],"correctIndex":1},"comments":[]}]'::jsonb),
  ('course-vue', 'Vue.js: De Cero a Aplicaciones Reales', 'Reactividad, directivas, componentes y Composition API — un curso completo de Vue.js, el otro gran framework de interfaces reactivas, con comparaciones directas a React.', 'Eres el Mago, tutor del curso de Vue.js en Oliver Academy. Este curso asume que algunos estudiantes ya tomaron el curso de React — haz comparaciones explícitas cuando ayuden a entender más rápido (props similares, pero reactividad distinta), sin asumir que es obligatorio conocer React primero.', '💚', '#42b883', 'Programación', 'Frontend Moderno', null, false, '[{"id":"vue-01","order":1,"type":"text","title":"¿Por qué Vue? Filosofía y comparación","description":"El framework diseñado para adoptarse gradualmente, pieza por pieza.","content":"<h2>Origen y filosofía</h2><p><strong>Vue.js</strong>, creado por Evan You en 2014, se diseñó explícitamente para ser fácil de adoptar de forma incremental — puedes usarlo para una sola parte interactiva de una página existente, sin tener que reescribir todo el proyecto, algo que en sus primeras versiones era más difícil con otros frameworks.</p><h2>Vue vs. React: similar meta, caminos distintos</h2><ul><li>Ambos son declarativos, basados en componentes, y reactivos.</li><li>React usa JSX (HTML dentro de JavaScript); Vue usa <strong>plantillas</strong> HTML con sintaxis especial (más parecidas a HTML tradicional).</li><li>React requiere <code>useState</code> explícito; Vue tiene un sistema de <strong>reactividad automática</strong> más directo, como verás en el próximo módulo.</li></ul><div class=\"tip\">💡 Ninguno es \"objetivamente mejor\" — ambos resuelven el mismo problema de construir interfaces reactivas, con filosofías de diseño distintas. Conocer ambos te da perspectiva real sobre las decisiones de diseño de cada uno, no solo memorizar sintaxis de uno.</div>","exercises":[{"id":"vue-01-1","type":"challenge","prompt":"¿Ya tomaste el curso de React? Si es así, anota una primera impresión sobre qué esperarías que sea distinto en Vue, basado en la filosofía de \"adopción incremental\" de este módulo. Compártelo con tu mascota.","solution":""}],"resources":[],"quiz":{"question":"Según este módulo, ¿qué diferencia principal de sintaxis hay entre React y Vue?","options":["Ninguna, son idénticos","React usa JSX (HTML en JS); Vue usa plantillas HTML con sintaxis especial","Vue no permite componentes","React no permite reactividad"],"correctIndex":1},"comments":[]},{"id":"vue-02","order":2,"type":"text","title":"Tu primer componente: plantilla y reactividad","description":"La anatomía de un componente Vue de un solo archivo.","content":"<h2>Un componente .vue: tres partes</h2><div class=\"example\">🧪 <code>&lt;template&gt;<br>&nbsp;&nbsp;&lt;h1&gt;Hola, {{ nombre }}!&lt;/h1&gt;<br>&lt;/template&gt;<br><br>&lt;script setup&gt;<br>const nombre = ''Ana''<br>&lt;/script&gt;</code></h2><p>La sección <code>&lt;template&gt;</code> contiene el HTML (con la sintaxis especial de Vue), y <code>&lt;script setup&gt;</code> contiene la lógica JavaScript — las variables definidas ahí están automáticamente disponibles en la plantilla, sin pasos adicionales.</p><h2>Interpolación de texto</h2><p>Las llaves dobles <code>{{ }}</code> insertan el valor de una variable de JavaScript directamente en el HTML — el equivalente de las llaves simples <code>{ }</code> en JSX de React.</p><div class=\"tip\">💡 Notarás que Vue separa explícitamente plantilla y lógica en secciones distintas del mismo archivo, mientras React las mezcla directamente en JSX — dos formas distintas de organizar la misma idea de \"componente\".</div>","exercises":[{"id":"vue-02-1","type":"challenge","prompt":"Escribe un componente Vue simple (con template y script setup) que muestre 2 variables usando interpolación de texto. Comparte tu código con tu mascota.","solution":""}],"resources":[],"quiz":{"question":"¿Qué sintaxis usa Vue para insertar el valor de una variable en el HTML de la plantilla?","options":["Llaves simples { }","Llaves dobles {{ }}","Corchetes [ ]","Paréntesis ( )"],"correctIndex":1},"comments":[]},{"id":"vue-03","order":3,"type":"text","title":"Data y reactividad: ref() y reactive()","description":"Cómo Vue detecta cambios automáticamente, sin necesitar una función setter explícita.","content":"<h2>ref(): una caja reactiva para un valor</h2><div class=\"example\">🧪 <code>&lt;script setup&gt;<br>import { ref } from ''vue''<br>const contador = ref(0)<br>function incrementar() {<br>&nbsp;&nbsp;contador.value++<br>}<br>&lt;/script&gt;<br><br>&lt;template&gt;<br>&nbsp;&nbsp;&lt;button @click=\"incrementar\"&gt;Clics: {{ contador }}&lt;/button&gt;<br>&lt;/template&gt;</code></h2><p><code>ref()</code> envuelve un valor en un objeto reactivo — dentro de <code>&lt;script&gt;</code> accedes con <code>.value</code>, pero en la plantilla Vue lo \"desenvuelve\" automáticamente (por eso <code>{{ contador }}</code> y no <code>{{ contador.value }}</code>).</p><h2>Comparado con useState de React</h2><p>A diferencia de <code>useState</code> (donde llamas explícitamente a <code>setContador</code>), con <code>ref()</code> simplemente modificas <code>contador.value</code> directamente y Vue detecta el cambio automáticamente — no hay una función setter separada.</p><h2>reactive(): para objetos completos</h2><div class=\"example\">🧪 <code>const usuario = reactive({ nombre: ''Ana'', edad: 16 })<br>usuario.edad++ // modificación directa, Vue lo detecta</code></div><div class=\"tip\">💡 <code>reactive()</code> es para objetos; <code>ref()</code> funciona para cualquier tipo de valor (incluidos objetos) — en la práctica, muchos desarrolladores de Vue usan <code>ref()</code> por defecto para mantener consistencia.</div>","exercises":[{"id":"vue-03-1","type":"challenge","prompt":"Compara la sintaxis de useState en React con ref() en Vue para el mismo contador. ¿Cuál te parece más directa? Justifica tu respuesta y comparte con tu mascota.","solution":""}],"resources":[],"quiz":{"question":"¿Cómo se actualiza un valor envuelto en ref() dentro del script, a diferencia de useState en React?","options":["Llamando a una función setter separada, igual que React","Modificando directamente su propiedad .value — Vue detecta el cambio automáticamente","No se puede actualizar nunca","Solo se puede leer, no modificar"],"correctIndex":1},"comments":[]},{"id":"vue-04","order":4,"type":"text","title":"Directivas: v-if, v-for, v-bind, v-on","description":"Los atributos especiales que le dan superpoderes al HTML de una plantilla Vue.","content":"<h2>v-if: renderizado condicional</h2><div class=\"example\">🧪 <code>&lt;p v-if=\"tareas.length === 0\"&gt;No hay tareas&lt;/p&gt;<br>&lt;p v-else&gt;Tienes {{ tareas.length }} tareas&lt;/p&gt;</code></div><h2>v-for: listas</h2><div class=\"example\">🧪 <code>&lt;li v-for=\"tarea in tareas\" :key=\"tarea.id\"&gt;<br>&nbsp;&nbsp;{{ tarea.titulo }}<br>&lt;/li&gt;</code><br>Igual que en React, el <code>:key</code> (equivalente a la prop <code>key</code>) es obligatorio para que Vue rastree correctamente cada elemento.</div><h2>v-bind (o :) y v-on (o @): conectar datos y eventos</h2><div class=\"example\">🧪 <code>&lt;img :src=\"usuario.foto\" /&gt;  &lt;!-- v-bind, forma corta: : --&gt;<br>&lt;button @click=\"guardar\"&gt;Guardar&lt;/button&gt;  &lt;!-- v-on, forma corta: @ --&gt;</code></div><p><code>v-bind</code> (abreviado <code>:</code>) conecta un atributo HTML a una variable de JavaScript. <code>v-on</code> (abreviado <code>@</code>) conecta un evento del DOM a una función.</p><div class=\"tip\">💡 Estas directivas son el equivalente directo de lo que en React se hace con JavaScript puro dentro de JSX (<code>{condicion &amp;&amp; <p>...</p>}</code>, <code>.map()</code>, <code>onClick={...}</code>) — Vue las convierte en atributos HTML especiales en vez de expresiones de JavaScript embebidas.</div>","exercises":[{"id":"vue-04-1","type":"challenge","prompt":"Escribe una plantilla Vue que use las 4 directivas del módulo (v-if, v-for con :key, v-bind, v-on) en un solo componente pequeño. Comparte tu código con tu mascota.","solution":""}],"resources":[],"quiz":{"question":"¿Qué hace la directiva v-on (o su forma corta @)?","options":["Renderiza una lista","Conecta un evento del DOM (como un clic) a una función de JavaScript","Oculta un elemento condicionalmente","Define una variable reactiva"],"correctIndex":1},"comments":[]},{"id":"vue-05","order":5,"type":"text","title":"Props y eventos entre componentes","description":"Cómo se comunican un componente padre y un componente hijo en Vue.","content":"<h2>Props: de padre a hijo</h2><div class=\"example\">🧪 <strong>Componente hijo (TarjetaCurso.vue):</strong><br><code>&lt;script setup&gt;<br>defineProps([''titulo'', ''descripcion''])<br>&lt;/script&gt;<br>&lt;template&gt;<br>&nbsp;&nbsp;&lt;h3&gt;{{ titulo }}&lt;/h3&gt;<br>&nbsp;&nbsp;&lt;p&gt;{{ descripcion }}&lt;/p&gt;<br>&lt;/template&gt;</code><br><strong>Componente padre:</strong><br><code>&lt;TarjetaCurso titulo=\"Vue.js\" descripcion=\"...\" /&gt;</code></div><p>Igual que en React, las props fluyen en una sola dirección: de padre a hijo, y el hijo no debe modificarlas directamente.</p><h2>Eventos personalizados: de hijo a padre</h2><div class=\"example\">🧪 <strong>Hijo:</strong> <code>&lt;button @click=\"$emit(''completado'')\"&gt;Marcar hecho&lt;/button&gt;</code><br><strong>Padre:</strong> <code>&lt;TarjetaTarea @completado=\"manejarCompletado\" /&gt;</code></div><p>Cuando un hijo necesita \"avisarle\" algo al padre, <strong>emite un evento personalizado</strong> con <code>$emit</code> — el padre escucha ese evento igual que escucharía un clic nativo del DOM. Es el equivalente de pasar una función como prop en React (<code>onCompletado={...}</code>), pero con una sintaxis de eventos explícita en vez de una prop-función.</p><div class=\"tip\">💡 El patrón de fondo es idéntico al de React: los datos bajan por props, las acciones suben mediante funciones/eventos — solo cambia la sintaxis específica de cada framework.</div>","exercises":[{"id":"vue-05-1","type":"challenge","prompt":"Diseña un componente hijo que reciba 2 props y emita un evento personalizado al hacer clic en un botón, más el componente padre que lo usa y escucha ese evento. Comparte tu código con tu mascota.","solution":""}],"resources":[],"quiz":{"question":"¿Cómo \"avisa\" un componente hijo algo a su padre en Vue?","options":["Modificando directamente una prop del padre","Emitiendo un evento personalizado con $emit, que el padre escucha","No es posible comunicar de hijo a padre","Recargando la página completa"],"correctIndex":1},"comments":[]},{"id":"vue-06","order":6,"type":"text","title":"Computed properties y watchers","description":"Valores derivados automáticamente, y cómo reaccionar cuando algo específico cambia.","content":"<h2>Computed: valores derivados que se actualizan solos</h2><div class=\"example\">🧪 <code>const precio = ref(100)<br>const cantidad = ref(3)<br>const total = computed(() =&gt; precio.value * cantidad.value)</code></div><p>Una <strong>propiedad computada</strong> se recalcula automáticamente cuando cualquiera de sus dependencias (<code>precio</code>, <code>cantidad</code>) cambia — sin necesitar que la vuelvas a calcular manualmente en cada lugar donde la uses. Es el equivalente conceptual de derivar un valor a partir del estado en React, pero con memorización automática incorporada.</p><h2>Watch: reaccionar a un cambio específico con un efecto</h2><div class=\"example\">🧪 <code>watch(cantidad, (nuevoValor, valorAnterior) =&gt; {<br>&nbsp;&nbsp;console.log(`Cambió de ${valorAnterior} a ${nuevoValor}`)<br>})</code></div><p><code>watch</code> ejecuta una función cuando un valor reactivo específico cambia — es el equivalente más cercano a <code>useEffect</code> de React con un array de dependencias específico, pero enfocado en \"reaccionar a UN cambio\" en vez de \"sincronizar con algo externo\" de forma más general.</p><div class=\"warn\">⚠️ Regla práctica: si solo necesitas un valor derivado para MOSTRAR algo, usa <code>computed</code> (más simple y eficiente). Si necesitas EJECUTAR una acción (una petición, un log) en respuesta a un cambio, usa <code>watch</code>.</div>","exercises":[{"id":"vue-06-1","type":"challenge","prompt":"Diseña un ejemplo propio con una computed property (para un valor derivado) y un watch (para reaccionar a un cambio con una acción, como un console.log). Comparte tu código con tu mascota.","solution":""}],"resources":[],"quiz":{"question":"¿Cuándo conviene usar \"computed\" en vez de \"watch\"?","options":["Nunca, siempre es mejor watch","Cuando solo necesitas un valor derivado para mostrar, no ejecutar una acción","Solo cuando hay errores en la app","Son exactamente intercambiables siempre"],"correctIndex":1},"comments":[]},{"id":"vue-07","order":7,"type":"text","title":"Composition API vs. Options API","description":"Cierre del curso: las dos formas de escribir componentes Vue, y por qué este curso usó una de ellas.","content":"<h2>Options API: el estilo clásico de Vue</h2><div class=\"example\">🧪 <code>export default {<br>&nbsp;&nbsp;data() { return { contador: 0 } },<br>&nbsp;&nbsp;methods: {<br>&nbsp;&nbsp;&nbsp;&nbsp;incrementar() { this.contador++ }<br>&nbsp;&nbsp;}<br>}</code></div><p>La <strong>Options API</strong> (el estilo original de Vue) organiza un componente en secciones fijas: <code>data</code>, <code>methods</code>, <code>computed</code>, etc. — clara y estructurada, especialmente para componentes simples.</p><h2>Composition API: el estilo que usó este curso</h2><p>La <strong>Composition API</strong> (con <code>&lt;script setup&gt;</code>, <code>ref()</code>, <code>computed()</code>) organiza el código por LÓGICA relacionada en vez de por tipo — más flexible para componentes complejos, y más fácil de compartir lógica reutilizable entre componentes (similar en espíritu a los hooks personalizados de React).</p><div class=\"tip\">💡 Este curso usó Composition API porque es el estilo recomendado para proyectos nuevos desde Vue 3 — pero encontrarás mucho código Vue existente (y documentación) usando Options API, así que reconocer ambos estilos es útil en la práctica real.</div><h2>Cierre del curso</h2><div class=\"tip\">💡 Con esto completas un curso completo de Vue.js: filosofía y comparación con React, plantillas y reactividad, ref()/reactive(), directivas, comunicación entre componentes, propiedades computadas/watchers, y finalmente las dos APIs de Vue. Entre este curso y el de React, ahora tienes una base comparativa real de los dos frameworks de interfaces más usados del desarrollo web moderno — no solo la sintaxis de uno aislado.</div>","exercises":[{"id":"vue-07-1","type":"challenge","prompt":"Reescribe brevemente (en pseudocódigo) el componente Contador del módulo 3 (que usó Composition API) en estilo Options API, con data() y methods. Comparte ambas versiones con tu mascota.","solution":""}],"resources":[],"quiz":{"question":"¿Por qué este curso usó Composition API en vez de Options API?","options":["Porque Options API ya no existe","Porque es el estilo recomendado para proyectos nuevos desde Vue 3, aunque Options API sigue siendo válida","Porque es obligatorio usar Composition API siempre","No hay ninguna razón real, es aleatorio"],"correctIndex":1},"comments":[]}]'::jsonb)
on conflict (id) do update set
  title = excluded.title, description = excluded.description, ai_instructions = excluded.ai_instructions,
  icon = excluded.icon, color = excluded.color, category = excluded.category, subcategory = excluded.subcategory,
  difficulty = excluded.difficulty, locked = excluded.locked, modules = excluded.modules, updated_at = now();
